function s(v) { return String(v == null ? '' : v).trim(); }
function nz(x) { return s(x).toLowerCase().replace(/[^a-z0-9]/g, ''); }

const trk = $('Read Deal Tracker').all().map(function (i) { return i.json; });
const invRaw = $('Read INVESTORS').all().map(function (i) { return i.json; });
const stRaw = $('Read STARTUPS').all().map(function (i) { return i.json; });
const pipe = $input.all().map(function (i) { return i.json; });
if (pipe.length < 500) { throw new Error('ABORT: PIPELINE only ' + pipe.length); }
if (trk.length < 200) { throw new Error('ABORT: tracker only ' + trk.length + ' rows - truncated'); }

const TAGS = [
  ['health', /health|medtech|bio|clinic|pharma|life science|wellness|fitness|diagnost|hospital|patient|doctor/],
  ['fintech', /fintech|lending|insur|payment|banking|wealth|credit|financial|neobank/],
  ['saas', /saas|b2b|enterprise|software|platform|api|devtool|cloud|workflow|automation/],
  ['consumer', /consumer|d2c|b2c|retail|fmcg|food|beverage|fashion|beauty|apparel|coffee|restaurant|cafe|grocer|kitchen|snack|personal care/],
  ['deeptech', /deeptech|deep tech|\bai\b|artificial intelligence|\bml\b|robot|iot|semiconductor|space|drone|quantum|computer vision|hardware/],
  ['climate', /climate|clean|energy|solar|ev\b|electric vehicle|sustain|green|water|waste|carbon|recycl/],
  ['edtech', /edtech|education|learning|skill|training|exam|student|course/],
  ['logistics', /logistic|supply chain|mobility|delivery|freight|shipping|transport|warehous/],
  ['agritech', /agri|farm|agtech|crop/],
  ['hrtech', /hrtech|\bhr\b|recruit|talent|hiring|staffing|workforce/],
  ['proptech', /proptech|real estate|construction|coworking|interior|windoor|building/],
  ['media', /media|gaming|content|entertainment|creator|social|dating|travel|music|video/]
];
function tagsOf(txt) {
  const t = s(txt).toLowerCase();
  const out = {};
  for (const p of TAGS) { if (p[1].test(t)) { out[p[0]] = 1; } }
  return Object.keys(out);
}
function startupStage(txt) {
  const t = s(txt).toLowerCase();
  if (/series b|growth|series c/.test(t)) { return 4; }
  if (/series a/.test(t)) { return 3; }
  if (/pilot|traction|early revenue|revenue|mvp|launched/.test(t)) { return 2; }
  if (/\bseed\b/.test(t) && !/pre-?seed/.test(t)) { return 1; }
  if (/pre-?seed|ideation|concept|idea|prototype/.test(t)) { return 0; }
  return 1;
}
function investorBand(txt) {
  const t = s(txt).toLowerCase();
  const h = [];
  if (/pre-?seed|preseed/.test(t)) { h.push(0); }
  if (/\bseed\b/.test(t)) { h.push(1); }
  if (/pilot|traction|early|pre-?series a|pre series a/.test(t)) { h.push(2); }
  if (/series a/.test(t)) { h.push(3); }
  if (/series b|series c|growth|late|pre-?ipo/.test(t)) { h.push(4); }
  if (!h.length) { return null; }
  return [Math.min.apply(null, h), Math.max.apply(null, h)];
}
function toCr(txt) {
  const t = s(txt).replace(/,/g, '');
  if (!t) { return null; }
  let m = t.match(/(?:US\$|\$)\s*([\d.]+)\s*M/i);
  if (m) { return parseFloat(m[1]) * 8.5; }
  m = t.match(/(?:US\$|\$)\s*([\d.]+)\s*K/i);
  if (m) { return parseFloat(m[1]) * 0.0085; }
  m = t.match(/([\d.]+)\s*(?:-|to|–)\s*[\d.]+\s*Cr/i);
  if (m) { return parseFloat(m[1]); }
  m = t.match(/([\d.]+)\s*Cr/i);
  if (m) { return parseFloat(m[1]); }
  m = t.match(/([\d.]+)\s*Lakh/i);
  if (m) { return parseFloat(m[1]) / 100; }
  return null;
}
const FLOOR_FIX = { a2dventures: 0.85, mintvc: 0.5, pipersireca: 1.0 };

const book = [];
const seenInv = {};
for (const r of invRaw) {
  const n = s(r.investor);
  if (!n) { continue; }
  if (s(r.do_not_contact).toLowerCase() === 'yes') { continue; }
  const k = nz(n);
  if (seenInv[k]) { continue; }
  seenInv[k] = 1;
  const sec = s(r.sector);
  let floor = toCr(r.cheque_inr_cr);
  if (FLOOR_FIX[k] !== undefined) { floor = FLOOR_FIX[k]; }
  book.push({ key: k, name: n, email: s(r.email), agnostic: /agno/i.test(sec),
    tags: tagsOf(sec), band: investorBand(r.stage), floor: floor });
}

const cols = Object.keys(trk[0] || {});
let cInv = null; const cDeals = [];
for (const c of cols) {
  const l = c.toLowerCase();
  if (!cInv && (l.indexOf('investor') >= 0 || l.indexOf('vc name') >= 0)) { cInv = c; }
  if (l.indexOf('deals shared') >= 0 || l.indexOf('latest deal') >= 0 || l.indexOf('picked') >= 0) { cDeals.push(c); }
}
const trkText = [];
for (const r of trk) {
  const iv = nz(r[cInv]);
  if (!iv) { continue; }
  let blob = '';
  for (const c of cDeals) { blob += ' ' + s(r[c]); }
  trkText.push({ inv: iv, blob: nz(blob) });
}
const pairedBy = {};
for (const p of pipe) {
  const k = nz(p.startup);
  if (!k) { continue; }
  if (!pairedBy[k]) { pairedBy[k] = {}; }
  pairedBy[k][nz(p.investor)] = 1;
}

function parseDate(v) {
  const t = s(v);
  if (!t) { return null; }
  let m = t.match(/^(\d{4})-(\d{2})-(\d{2})/);
  if (m) { return new Date(Date.UTC(+m[1], +m[2] - 1, +m[3])); }
  m = t.match(/^(\d{1,2})[\/-](\d{1,2})[\/-](\d{4})/);
  if (m) { return new Date(Date.UTC(+m[3], +m[2] - 1, +m[1])); }
  const dd = new Date(t);
  return isNaN(dd.getTime()) ? null : dd;
}
const TODAY = new Date(Date.UTC(2026, 8, 10));

// real throughput: what actually went out over the last 30 days, per weekday
let sent30 = 0;
for (const p of pipe) {
  if (s(p.deal_shared).toLowerCase() !== 'yes') { continue; }
  const dd = parseDate(p.date_shared);
  if (dd && (TODAY - dd) / 86400000 <= 30 && dd <= TODAY) { sent30++; }
}
let cap = Math.round(sent30 / 22);
if (cap < 10) { cap = 10; }
if (cap > 30) { cap = 30; }

// days already spoken for by deals queued and not yet sent
const load = {};
for (const p of pipe) {
  if (s(p.deal_shared).toLowerCase() === 'yes') { continue; }
  if (s(p.pause).toLowerCase() === 'yes') { continue; }
  const dd = parseDate(p.next_due);
  if (!dd) { continue; }
  const key = dd.toISOString().slice(0, 10);
  load[key] = (load[key] || 0) + 1;
}

const hits = [];
const perStartup = {};
for (const r of stRaw) {
  const name = s(r.startup);
  if (!name || s(r.active).toLowerCase() !== 'yes') { continue; }
  const k = nz(name);
  const paired = Object.assign({}, pairedBy[k] || {});
  for (const t of trkText) { if (k.length > 3 && t.blob.indexOf(k) >= 0) { paired[t.inv] = 1; } }

  const sTags = tagsOf(s(r.sector));
  const si = startupStage(r.stage);
  const raise = toCr(r.raise_inr_cr);
  const owner = s(r.owner);

  for (const b of book) {
    if (paired[b.key]) { continue; }
    // SECTOR strict
    let overlap = false;
    for (const t of b.tags) { if (sTags.indexOf(t) >= 0) { overlap = true; break; } }
    const secOK = b.agnostic || overlap;
    if (!secOK) { continue; }
    // STAGE strict - stated band only, no stretch
    if (b.band !== null && !(si >= b.band[0] && si <= b.band[1])) { continue; }
    // CHEQUE lenient - floor only, they can co-invest a slice of any larger round
    let chqPts;
    if (b.floor === null) { chqPts = 20; }
    else if (raise !== null && raise >= b.floor) { chqPts = 30; }
    else { continue; }
    const score = (overlap ? 40 : 28) + 30 + chqPts;
    hits.push({ startup: name, owner: owner, investor: b.name, email: b.email, score: score });
    perStartup[name] = (perStartup[name] || 0) + 1;
  }
}
if (hits.length === 0) { throw new Error('ABORT: no matches produced'); }
if (hits.length > 1100) { throw new Error('ABORT: ' + hits.length + ' rows exceeds guard of 1100'); }

// best deals first, and rotate startups so no single one hogs the early dates
hits.sort(function (a, b) { return b.score - a.score || a.startup.localeCompare(b.startup); });
const buckets = {};
for (const h of hits) { if (!buckets[h.startup]) { buckets[h.startup] = []; } buckets[h.startup].push(h); }
const names = Object.keys(buckets).sort();
const ordered = [];
let more = true;
while (more) {
  more = false;
  for (const nm of names) {
    const arr = buckets[nm];
    if (arr.length) { ordered.push(arr.shift()); more = true; }
  }
}

let maxN = 0;
for (const p of pipe) {
  const id = s(p.deal_id);
  if (id.charAt(0) === 'D') { const v = parseInt(id.slice(1), 10); if (!isNaN(v) && v > maxN) { maxN = v; } }
}

// walk forward from tomorrow, only filling weekdays that are under the cap
const cursor = new Date(TODAY.getTime());
cursor.setUTCDate(cursor.getUTCDate() + 1);
function nextSlot() {
  for (let guard = 0; guard < 2000; guard++) {
    const w = cursor.getUTCDay();
    if (w !== 0 && w !== 6) {
      const key = cursor.toISOString().slice(0, 10);
      if ((load[key] || 0) < cap) { load[key] = (load[key] || 0) + 1; return key; }
    }
    cursor.setUTCDate(cursor.getUTCDate() + 1);
  }
  throw new Error('ABORT: could not place a row within 2000 days');
}

let n = maxN;
const out = ordered.map(function (h) {
  n++;
  let pad = String(n);
  while (pad.length < 5) { pad = '0' + pad; }
  return { json: { deal_id: 'D' + pad, startup: h.startup, owner: h.owner, investor: h.investor,
    email: h.email, cc: '', priority: h.score, deal_shared: 'No', next_action: 'Initial',
    next_due: nextSlot(),
    notes: (h.score >= 85 ? 'Very High' : 'High') + ' match (' + h.score + ') - strict sector+stage re-match 2026-09-10' } };
});
const first = out[0].json.next_due, last = out[out.length - 1].json.next_due;
console.log('rows ' + out.length + ' cap/weekday ' + cap + ' sent30 ' + sent30 +
  ' spanning ' + first + ' to ' + last + ' :: ' + JSON.stringify(perStartup));
return out;
